		t.Fatal(err)
	}
	code, out, errOut := runDispatch(t, reviewArgs(damagedPath, org, 2, cp.EndSeq, cp.Fingerprint)...)
	if code != 1 {
		t.Fatalf("late-record damage exit = %d, want 1; %s", code, errOut)
	}
	if out != "" {
		t.Fatalf("no partial output allowed, got %q", out)
	}
}

